var EXTRA=[{dot:"gray",j:"Journal of ISAKOS",h:"In laboratorio due tecniche di sutura per la radice meniscale si equivalgono",v:"Modello suino su ventotto menischi: cambiare lo schema di sutura o il sistema di fissazione tibiale non cambia la tenuta iniziale del costrutto — il punto debole resta sempre l'interfaccia fra sutura e tessuto.",pmid:'42731677',doi:'10.1016/j.jisako.2026.101219',temi:["menisco","radice meniscale","biomeccanica"]},{dot:"gray",j:"Frontiers in Public Health",h:"L'allenamento neuromuscolare riduce gli infortuni al ginocchio a ogni età",v:"Meta-analisi di trenta studi: i programmi multicomponente e standardizzati funzionano meglio di quelli generici, senza un chiaro vantaggio legato all'età dell'atleta.",pmid:'42730390',doi:'10.3389/fpubh.2026.1822715',temi:["prevenzione infortuni","allenamento neuromuscolare","lca"]},{dot:"gray",j:"Frontiers in Surgery",h:"Un caso cinese: l'osteotomia femorale corretta al volo dal robot durante la protesi",v:"Caso singolo con deformità femorale extra-articolare severa: il sistema robotico ha ripianificato in sala l'osteotomia dopo che la prova d'impianto mostrava un blocco in estensione.",pmid:'42729879',doi:'10.3389/fsurg.2026.1910960',temi:["protesi robotica","osteotomia femorale","caso clinico"]},{dot:"gray",j:"Scientific Reports",h:"La posizione di anca e ginocchio cambia la rigidità del quadricipite misurata",v:"Studio su soggetti sani: la rigidità del retto femorale e del vasto laterale, misurata con elastografia, dipende dall'angolo articolare scelto per il test — un avvertimento per chi confronta misure fatte in posizioni diverse.",pmid:'42728264',doi:'10.1038/s41598-026-60808-z',temi:["biomeccanica","quadricipite","elastografia"]},{dot:"gray",j:"The International Journal, Advanced Manufacturing Technology",h:"Un inserto tibiale a struttura auxetica, pensato su misura del peso del paziente",v:"Studio ingegneristico: forme reticolari auxetiche, che si restringono sotto compressione, promettono un inserto tibiale più leggero e adattabile a pazienti di peso diverso — test di laboratorio, non ancora un impianto reale.",pmid:'42729595',doi:'10.1007/s00170-026-18816-w',temi:["ingegneria dei materiali","protesi di ginocchio","stampa 3d"]},{dot:"gray",j:"Cellular and Molecular Bioengineering",h:"La bioprinting 3D della cartilagine, una rassegna dei progressi recenti",v:"Rassegna narrativa sulle tecniche di stampa tridimensionale per rigenerare la cartilagine: descrive i progressi di laboratorio e gli ostacoli ancora aperti prima di un uso clinico.",pmid:'42729689',doi:'10.1007/s12195-026-00926-w',temi:["bioingegneria","cartilagine","stampa 3d"]},{dot:"gray",j:"Biomechanics and Modeling in Mechanobiology",h:"Un modello computazionale spiega perché l'innesto osteocondrale rotuleo può cedere al bordo",v:"Simulazione agli elementi finiti: quando spessore o rigidità della cartilagine del donatore non combaciano con quella del ricevente, lo sforzo si concentra proprio al bordo dell'innesto — un argomento per scegliere meglio la compatibilità del donatore.",pmid:'42730942',doi:'10.1007/s10237-026-02128-9',temi:["cartilagine","innesto osteocondrale","biomeccanica computazionale"]},{dot:"gray",j:"Journal of the Mechanical Behavior of Biomedical Materials",h:"La deformazione trasversale del tendine rotuleo dipende da come è fatto il tessuto",v:"Studio di laboratorio sul tendine rotuleo umano: la composizione e la struttura locali del tessuto spiegano la sua deformazione sotto carico meglio di un modello uniforme — rilevante per chi lo preleva come innesto.",pmid:'42731349',doi:'10.1016/j.jmbbm.2026.107634',temi:["biomeccanica dei tessuti","tendine rotuleo","innesto"]},{dot:"gray",j:"Journal of the International Society of Sports Nutrition",h:"La creatina in aggiunta alla riabilitazione nella tendinopatia rotulea",v:"Studio con supplementazione, insieme alla riabilitazione, per accelerare il rientro allo sport nella tendinopatia rotulea: un possibile aiuto in più sul dolore, ancora da confermare su casistiche più ampie.",pmid:'42730713',doi:'10.1080/15502783.2026.2718846',temi:["tendinopatia rotulea","integrazione","rientro allo sport"]},{dot:"gray",j:"The Journal of the American Academy of Orthopaedic Surgeons",h:"Le protesi di ginocchio si spostano sempre più verso la chirurgia ambulatoriale",v:"Una proiezione sui volumi di protesi totale di ginocchio negli Stati Uniti stima una crescita costante del setting ambulatoriale rispetto al ricovero tradizionale, dopo la rimozione dalla lista Medicare dei soli interventi in regime di ricovero — un tema organizzativo, non clinico.",pmid:'42725752',doi:'10.5435/JAAOS-D-26-00047',temi:["organizzazione sanitaria","protesi totale","chirurgia ambulatoriale"]},{dot:"gray",j:"Surgical and Radiologic Anatomy",h:"Una mappa in 3D del volume e della densità della rotula, oltre le misure lineari",v:"Studio anatomico turco su tomografia computerizzata: propone un'analisi tridimensionale più completa della sola misura lineare per descrivere la rotula, con differenze marcate fra i sessi.",pmid:'42726139',doi:'10.1007/s00276-026-03998-5',temi:["anatomia","rotula","imaging"]}];
var SCOPERTE=[{t:"Un'intelligenza artificiale legge l'osteoporosi da una semplice radiografia del ginocchio",v:"Un gruppo indiano ha addestrato una rete neurale che combina localizzazione automatica dell'articolazione e analisi delle texture ossee per classificare osteopenia e osteoporosi da normali radiografie di ginocchio, con l'obiettivo di aiutare il radiologo, non sostituirlo. Resta uno studio tecnico su un solo centro, lontano dalla validazione clinica prospettica.",pmid:'42731440',doi:'10.1016/j.compbiolchem.2026.109399',temi:["intelligenza artificiale","osteoporosi","imaging"]},{t:"La metformina, farmaco antidiabetico, allo studio per riparare la cartilagine",v:"Una rassegna cinese riunisce le prove precliniche su come la metformina, già diffusa contro il diabete, possa proteggere la cartilagine attraverso più meccanismi molecolari insieme. I primi segnali clinici sono descritti come promettenti, ma gli stessi autori chiedono studi prospettici su larga scala prima di qualunque uso reale.",pmid:'42729817',doi:'10.3389/fimmu.2026.1916957',temi:["farmaco riposizionato","cartilagine","ricerca traslazionale"]},{t:"Idrogel su misura per rigenerare il menisco, dalla chimica dei materiali alla clinica",v:"Una rassegna riunisce i progressi su idrogel naturali, sintetici e ibridi pensati per riparare il menisco: lubrificazione, adesione al tessuto umido, resistenza alla fatica meccanica. Gli stessi autori elencano gli ostacoli concreti alla traduzione clinica — produzione su scala, sterilizzazione, pochi dati da studi clinici veri.",pmid:'42731133',doi:'10.1016/j.colsurfb.2026.116170',temi:["bioingegneria","menisco","biomateriali"]}];
var SOC={"1":{"video":"Il rinforzo laterale, il LET, si esegue oggi insieme alla ricostruzione del legamento crociato anteriore in molti centri, compreso questo. Un grande studio su dati assicurativi americani, oltre diecimila pazienti confrontati a coppie simili, guarda che cosa succede aggiungendolo davvero. Chi riceve il LET ha più interventi per rigidità del ginocchio nel primo anno, più interventi sul menisco negli anni successivi, e più diagnosi di artrosi a cinque anni — un rischio più che raddoppiato — senza che si riduca la probabilità di dover rioperare il legamento. È un dato da dati assicurativi, non da un confronto clinico diretto, e non distingue quale tipo di innesto o di rinforzo sia stato usato: nei pazienti più giovani il segnale va anzi nella direzione opposta. Non basta a cambiare la pratica di chi lo esegue su ogni paziente, ma è la prima fotografia dei costi, non solo dei vantaggi, di questo gesto aggiuntivo."},"2":{"video":"Quando si ricostruisce il legamento che stabilizza la rotula, l'MPFL, la si può fissare sulla rotula con una piccola ancora a sutura oppure con un tunnel scavato nell'osso. Uno studio di laboratorio ha confrontato le due tecniche su rotule di bambini. Il tunnel osseo ha retto un carico molto più alto prima di cedere — quasi il triplo dell'ancora a sutura. La tenuta iniziale delle due tecniche sotto un carico leggero era invece simile. È un test di laboratorio, su rotule di cadavere e non su pazienti reali, con un campione piccolo. Un segnale utile per chi valuta la fissazione nei ragazzi più giovani con ossa meno dense, non ancora una prova definitiva."},"3":{"video":"Quando la ricostruzione del legamento crociato anteriore fallisce in un atleta che ha anche una tibia con un'inclinazione naturale aumentata, alcuni chirurghi correggono anche quell'inclinazione durante la revisione. Uno studio ha seguito diciannove atleti d'élite operati così. Tutti sono tornati allo sport al livello di prima dell'infortunio, in media dopo un anno, con punteggi funzionali molto migliorati e nessun nuovo fallimento del legamento. Manca un gruppo di confronto operato con la sola revisione: non si sa quanto del merito sia della correzione aggiunta. Resta però uno dei segnali più incoraggianti su questa strategia in chi ha già fallito una prima ricostruzione."},"4":{"video":"Quando si corregge chirurgicamente l'inclinazione della tibia, l'osteotomia si può fissare con una placca metallica oppure con una placca biodegradabile che il corpo riassorbe nel tempo. Uno studio di laboratorio ha confrontato le due tecniche sotto carichi ripetuti. Il carico che ha rotto l'osso alla fine era simile fra le due tecniche. Ma la placca biodegradabile si è mossa un po' di più durante i carichi ripetuti, cosa che non è successa con quella metallica. Gli autori stessi dicono di non poter dire quale tecnica sia migliore, con solo sei campioni per gruppo. Non cambia oggi la scelta della sintesi, ma è un'informazione tecnica utile per il futuro."},"5":{"video":"Quando si pianifica una protesi di ginocchio, oggi si guarda sempre di più anche all'inclinazione naturale del femore, non solo all'allineamento della gamba. Per misurarla di solito serve una TC. Uno studio ha provato a misurare questa inclinazione su una semplice radiografia laterale del ginocchio, confrontando il risultato con quello della TC su quarantotto ginocchia. Il risultato: le due misure si sono accordate molto bene, e la misura sulla radiografia è risultata affidabile anche ripetuta da persone diverse. Un passo verso una pianificazione più personalizzata senza bisogno di sempre una TC in più."},"6":{"video":"Dopo una protesi di ginocchio, alcuni pazienti sentono l'articolazione poco stabile quando la piegano, un problema spesso difficile da riconoscere con i test classici. Uno studio ha provato due strumenti su centoquarantacinque ginocchia protesizzate. Una radiografia fatta mettendosi in ginocchio sotto carico, insieme a un segno rilevabile alla visita, si sono associati davvero a questa instabilità riferita dal paziente. Il test classico, invece, non ha aiutato a distinguere. La capacità di questi strumenti di distinguere resta però solo modesta: utili in più, non da soli, insieme alla valutazione clinica completa del chirurgo."}};
var SOCV={"1":{"video":{"chir":["Un rinforzo laterale extra-articolare, il LET, si aggiunge oggi quasi ovunque alla ricostruzione del legamento crociato anteriore. Una coorte su oltre diecimila pazienti del database claims TriNetX, appaiati per propensity score, ha confrontato chi lo riceve con chi ha la sola ricostruzione.","Il risultato: con il LET più interventi per artrofibrosi nel primo anno, più chirurgia meniscale successiva a due anni, e più artrosi di ginocchio codificata a cinque anni — con un rischio più che raddoppiato. Nessuna riduzione dimostrata della nuova ricostruzione nell'analisi principale.","Il limite è importante: dati amministrativi, nessuna distinzione per tipo di innesto né per costrutto del LET, e possibile confondimento per indicazione. Nei pazienti più giovani, fra dodici e venticinque anni, il segnale va anzi nella direzione opposta. Non chiude la domanda sull'innesto rigido, apre un conto sui costi del gesto universale."],"misto":["Il rinforzo laterale, il LET, si esegue oggi insieme alla ricostruzione del legamento crociato anteriore in molti centri, compreso questo. Un grande studio su dati assicurativi americani, oltre diecimila pazienti confrontati a coppie simili, guarda che cosa succede aggiungendolo davvero.","Chi riceve il LET ha più interventi per rigidità del ginocchio nel primo anno, più interventi sul menisco negli anni successivi, e più diagnosi di artrosi a cinque anni — un rischio più che raddoppiato — senza che si riduca la probabilità di dover rioperare il legamento.","È un dato da dati assicurativi, non da un confronto clinico diretto, e non distingue quale tipo di innesto o di rinforzo sia stato usato: nei pazienti più giovani il segnale va anzi nella direzione opposta. Non basta a cambiare la pratica di chi lo esegue su ogni paziente, ma è la prima fotografia dei costi, non solo dei vantaggi, di questo gesto aggiuntivo."],"pazienti":["Quando si ricostruisce il legamento crociato del ginocchio, spesso si aggiunge un piccolo gesto in più su un lato del ginocchio, pensato per renderlo più stabile nei movimenti di torsione. Un grande studio americano ha confrontato chi lo riceve con chi no.","Chi ha ricevuto questo gesto aggiuntivo ha avuto più spesso un ginocchio rigido da trattare nel primo anno, più interventi sul menisco negli anni dopo, e più diagnosi di artrosi a cinque anni, senza che diminuisse il bisogno di rioperare il legamento.","È uno studio basato su archivi assicurativi, non un confronto diretto e controllato, e i pazienti più giovani nello studio hanno mostrato invece un vantaggio. Non è una risposta definitiva, ma un segnale importante da discutere col proprio chirurgo prima di un intervento di questo tipo."]},"linkedin":{"chir":["Coorte propensity-matched su database TriNetX (n=5021 per braccio): l'aggiunta del LET alla ACLR primaria si associa a più procedure per artrofibrosi a 1 anno (OR 1,65; IC 95% 1,29-2,11), più chirurgia meniscale successiva a 2 anni (HR 1,25) e più artrosi codificata a 5 anni (HR 2,24; IC 95% 1,76-2,85) — senza riduzione significativa della nuova ACLR nell'analisi primaria.","Limiti dichiarati dagli autori: dati amministrativi (CPT/ICD), nessuna stratificazione per tipo di innesto né per costrutto del LET (onlay/profondo, Lemaire o altro), possibile confondimento per indicazione. Nel sottogruppo 12-25 anni il segnale si inverte: minore probabilità di nuova ACLR a 1 anno con il LET.","Non isola il tuo innesto rigido né il costrutto onlay che esegui su ogni paziente: la domanda specifica su tendine quadricipitale resta aperta. Ma è il primo bilancio su scala reale — oltre diecimila pazienti — dei costi del gesto, non solo dei suoi benefici."],"misto":["Un rinforzo laterale, il LET, si aggiunge sempre più spesso alla ricostruzione del crociato anteriore. Uno studio su un grande database assicurativo americano (oltre diecimila pazienti appaiati a coppie simili) ha confrontato chi lo riceve con chi ha la sola ricostruzione.","Con il LET si osservano più interventi per rigidità del ginocchio nel primo anno, più chirurgia meniscale negli anni successivi e più diagnosi di artrosi a cinque anni, senza una riduzione dimostrata del bisogno di rioperare il legamento.","È uno studio osservazionale su dati assicurativi, non un confronto clinico diretto: non distingue il tipo di innesto né la tecnica del rinforzo, e nei pazienti più giovani il segnale è opposto. Un primo conto sui costi del gesto, utile nel colloquio prima dell'intervento."],"pazienti":["Nella ricostruzione del legamento crociato del ginocchio si aggiunge spesso un piccolo gesto extra su un lato dell'articolazione, per renderla più stabile nei movimenti di torsione. Un ampio studio americano ha confrontato chi lo riceve con chi no.","I pazienti che hanno ricevuto questo gesto in più hanno avuto più spesso bisogno di un intervento per un ginocchio rigido, più interventi sul menisco negli anni seguenti, e più diagnosi di artrosi dopo cinque anni.","Lo studio si basa su archivi assicurativi, non su un confronto diretto controllato, e nei pazienti più giovani il vantaggio è andato nella direzione opposta. Un buon argomento per parlarne con il proprio chirurgo prima di un intervento del genere."]},"instagram":{"chir":["LET + ACLR su TriNetX, n=5021/braccio: più artrofibrosi (OR 1,65), più chirurgia meniscale (HR 1,25), più artrosi codificata a 5 anni (HR 2,24). Nessuna riduzione della nuova ACLR.","Limiti: dati claims, nessuna stratificazione per innesto o costrutto del LET, confondimento per indicazione plausibile. Nei 12-25 anni il segnale si inverte.","Non risponde alla domanda sull'innesto rigido, ma è il primo conto reale sui costi del LET universale, non solo sui benefici."],"misto":["Il rinforzo laterale aggiunto al crociato anteriore (LET) è sempre più diffuso. Un grande studio su dati assicurativi americani ha guardato che cosa succede davvero ad aggiungerlo.","Con il LET: più interventi per rigidità nel primo anno, più chirurgia sul menisco dopo, più diagnosi di artrosi a 5 anni. Nessun calo del bisogno di rioperare il legamento.","Studio osservazionale, non un confronto clinico diretto, e nei pazienti più giovani il segnale si inverte. Un primo bilancio dei costi, non solo dei vantaggi."],"pazienti":["Nella ricostruzione del crociato del ginocchio si aggiunge spesso un piccolo gesto extra per renderlo più stabile nei movimenti di torsione.","Un grande studio americano mostra che chi lo riceve ha più spesso bisogno di un intervento per ginocchio rigido, più interventi sul menisco dopo, e più diagnosi di artrosi a 5 anni.","Non è un confronto diretto e controllato, e nei pazienti più giovani il vantaggio è andato nella direzione opposta. Da discutere con il proprio chirurgo prima dell'intervento."]},"reel":{"chir":["Il LET aggiunto alla ACLR: su oltre diecimila pazienti, più artrofibrosi e più chirurgia meniscale successiva.","A cinque anni, più del doppio il rischio di artrosi codificata. Nessun calo della nuova ACLR.","Non isola il tuo innesto né il tuo costrutto onlay: la lacuna resta, ma il conto dei costi ora esiste."],"misto":["Il rinforzo laterale aggiunto al crociato: più rigidità del ginocchio, più interventi sul menisco dopo.","A cinque anni più diagnosi di artrosi, più del doppio del rischio, senza vantaggi dimostrati sul reintervento.","Studio su dati assicurativi, non un confronto diretto: nei più giovani il segnale si inverte."],"pazienti":["Un gesto extra spesso aggiunto quando si ricostruisce il legamento del ginocchio: rende più stabile nella torsione.","Uno studio americano mostra più problemi di rigidità e più interventi sul menisco in chi lo riceve.","Da discutere con il proprio chirurgo: nei pazienti più giovani il vantaggio è stato opposto."]}},"2":{"video":{"chir":["La ricostruzione del legamento patello-femorale mediale, l'MPFL, si fissa sulla rotula con un'ancora a sutura oppure con un tunnel osseo. Uno studio cadaverico pediatrico ha confrontato le due tecniche su rotule di bambini fra nove e undici anni.","Il tunnel osseo ha retto un carico di rottura molto più alto dell'ancora a sutura, circa tre volte superiore. La rigidità del costrutto era simile fra le due tecniche, ma su un campione minuscolo.","È un test a tempo zero, senza carico ciclico né guarigione reale, su un solo modello di ancora. Un segnale biomeccanico da conoscere per la fissazione patellare nel paziente più giovane e con osso meno denso."],"misto":["Quando si ricostruisce il legamento che stabilizza la rotula, l'MPFL, la si può fissare sulla rotula con una piccola ancora a sutura oppure con un tunnel scavato nell'osso. Uno studio di laboratorio ha confrontato le due tecniche su rotule di bambini.","Il tunnel osseo ha retto un carico molto più alto prima di cedere — quasi il triplo dell'ancora a sutura. La tenuta iniziale delle due tecniche sotto un carico leggero era invece simile.","È un test di laboratorio, su rotule di cadavere e non su pazienti reali, con un campione piccolo. Un segnale utile per chi valuta la fissazione nei ragazzi più giovani con ossa meno dense, non ancora una prova definitiva."],"pazienti":["Nei ragazzi che hanno la rotula instabile si ricostruisce spesso un legamento interno che la trattiene, fissandolo con una piccola ancora oppure con un piccolo tunnel nell'osso della rotula.","Uno studio di laboratorio su rotule di bambini ha mostrato che il tunnel nell'osso regge un carico molto più alto prima di cedere rispetto alla piccola ancora.","È uno studio fatto in laboratorio, non su pazienti operati davvero, e con pochi campioni. Un'informazione utile per il chirurgo quando sceglie come fissare l'intervento nei ragazzi più giovani."]},"linkedin":{"chir":["Studio cadaverico controllato, 10 rotule pediatriche (6 donatori, 9-11 anni): fissazione patellare per MPFLR con ancora a sutura (2x1,8mm) vs tunnel osseo (2x2mm). Carico a rottura significativamente più alto con tunnel osseo (169,8±88,6N vs 55,3±20,1N; p=0,002).","Rigidità sovrapponibile fra le due tecniche (6±1,9 vs 6,4±1,7 N/mm; p=0,647), ma su soli 5 campioni per gruppo — l'assenza di differenza non dimostra equivalenza. Meccanismo di cedimento: sfilamento dell'ancora vs taglio della sutura nell'osso.","Tu fissi l'MPFL con ancore FiberTak in tecnica onlay, anche nei pazienti dai 14 anni. Primo dato biomeccanico pediatrico specifico su ancora vs tunnel osseo: un segnale, non ancora una ragione per cambiare tecnica, ma da tenere presente nell'adolescente con bassa densità ossea."],"misto":["La ricostruzione del legamento patello-femorale mediale (MPFL), che stabilizza la rotula, si può fissare con una piccola ancora a sutura oppure con un tunnel scavato nell'osso. Uno studio di laboratorio ha confrontato le due tecniche su rotule pediatriche di cadavere.","Il tunnel osseo ha retto un carico di rottura molto più alto — quasi il triplo — rispetto all'ancora a sutura. La tenuta sotto carichi leggeri era invece simile fra le due tecniche.","È un test di laboratorio su un campione piccolo, non uno studio clinico su pazienti operati: un segnale utile per la scelta della fissazione nei pazienti più giovani con ossa meno dense, non ancora una prova definitiva."],"pazienti":["Quando la rotula si lussa ripetutamente in un adolescente, si ricostruisce spesso un piccolo legamento interno (MPFL) che la trattiene, fissandolo con una piccola ancora oppure con un tunnel nell'osso della rotula.","Uno studio di laboratorio su rotule pediatriche ha mostrato che il tunnel nell'osso regge un carico molto più alto prima di cedere rispetto alla piccola ancora a sutura.","È uno studio di laboratorio, non un confronto su pazienti operati davvero: un'informazione tecnica in più per il chirurgo quando sceglie come fissare l'intervento nei più giovani."]},"instagram":{"chir":["MPFLR pediatrica: ancora a sutura vs tunnel osseo, 10 rotule cadaveriche. Tunnel osseo: carico a rottura quasi 3x superiore (169,8N vs 55,3N; p=0,002).","Rigidità simile, ma n=5/gruppo: non è prova di equivalenza. Cedimento sempre per sfilamento dell'ancora o taglio della sutura nell'osso.","Tu usi ancore FiberTak onlay: primo dato pediatrico specifico, segnale da conoscere nell'adolescente con bassa densità ossea."],"misto":["Fissare l'MPFL sulla rotula: ancora a sutura o tunnel osseo? Uno studio su rotule pediatriche di laboratorio confronta le due tecniche.","Il tunnel osseo regge quasi il triplo del carico prima di cedere rispetto all'ancora a sutura. Tenuta iniziale simile a carichi leggeri.","Studio di laboratorio, campione piccolo: un segnale utile per i pazienti più giovani, non ancora una prova definitiva."],"pazienti":["Quando la rotula di un ragazzo si lussa spesso, si ricostruisce un piccolo legamento interno che la trattiene.","Uno studio di laboratorio mostra che fissarlo con un tunnel nell'osso regge di più di una piccola ancora.","È un test di laboratorio, non uno studio su pazienti reali: un'informazione tecnica in più per il chirurgo."]},"reel":{"chir":["MPFL pediatrico: tunnel osseo o ancora a sutura per fissare la rotula?","Il tunnel osseo regge quasi 3 volte il carico dell'ancora, prima di cedere.","Segnale da laboratorio, campione piccolo: utile nell'adolescente con osso meno denso."],"misto":["Fissare il legamento della rotula: ancora o tunnel nell'osso?","In laboratorio, il tunnel osseo regge molto di più prima di cedere.","Solo un test di laboratorio, non ancora una prova definitiva sui pazienti."],"pazienti":["Quando la rotula di un ragazzo esce spesso dal suo posto, si ricostruisce un piccolo legamento.","Un test di laboratorio mostra che fissarlo con un tunnel nell'osso tiene di più.","Non è ancora uno studio su pazienti veri, ma un'informazione utile per il chirurgo."]}},"3":{"video":{"chir":["Quando la ricostruzione del crociato anteriore fallisce in un atleta con slope tibiale aumentato, correggere lo slope insieme alla revisione è una strategia sempre più discussa. Una serie di diciannove atleti d'élite operati in due centri l'ha messa alla prova.","Tutti gli atleti sono tornati in campo al livello pre-infortunio, in media dopo dodici mesi. I punteggi funzionali sono migliorati in modo netto e nessun innesto è fallito di nuovo.","È una serie senza gruppo di confronto: non si può dire quanto del merito sia dell'osteotomia e quanto della sola revisione. Ma è uno dei segnali più diretti finora su questa strategia in un profilo di paziente ad alto rischio."],"misto":["Quando la ricostruzione del legamento crociato anteriore fallisce in un atleta che ha anche una tibia con un'inclinazione naturale aumentata, alcuni chirurghi correggono anche quell'inclinazione durante la revisione. Uno studio ha seguito diciannove atleti d'élite operati così.","Tutti sono tornati allo sport al livello di prima dell'infortunio, in media dopo un anno, con punteggi funzionali molto migliorati e nessun nuovo fallimento del legamento.","Manca un gruppo di confronto operato con la sola revisione: non si sa quanto del merito sia della correzione aggiunta. Resta però uno dei segnali più incoraggianti su questa strategia in chi ha già fallito una prima ricostruzione."],"pazienti":["Quando l'intervento al legamento del ginocchio non tiene e serve rioperare, in alcuni casi il chirurgo corregge anche la forma naturale dell'osso della tibia, che può favorire un nuovo cedimento.","In un gruppo di diciannove sportivi d'élite operati così, tutti sono tornati allo sport al livello di prima, in media dopo un anno, senza che il nuovo intervento cedesse.","Manca un confronto con chi ha fatto solo la revisione senza questa correzione aggiuntiva: un risultato incoraggiante, non ancora una prova definitiva, ma utile a sapere per chi affronta un secondo intervento."]},"linkedin":{"chir":["Serie di casi, 2 centri (Barcellona/Lione): 19 atleti d'élite con LCA fallito e slope tibiale posteriore ≥10°, revisione ACLR + osteotomia sovratuberositaria di riduzione dello slope. Follow-up medio 58,8 mesi.","Rientro allo sport al livello pre-infortunio nel 100% dei casi (media 12,1 mesi). IKDC 44,2→92,3 (IC 95% 42-54; p<0,001); Lysholm 46,8→96,9. Slope medio da 14,9° a 4,5°. Nessun fallimento dell'innesto.","Serie a braccio unico, livello IV dichiarato: non isola l'effetto dell'osteotomia da quello della revisione. Tu esegui correzioni di slope — uno dei segnali più diretti finora su questa combinazione nell'atleta ad alto rischio di re-fallimento."],"misto":["Quando la ricostruzione del legamento crociato anteriore fallisce in un atleta con un'inclinazione tibiale naturale aumentata, alcuni centri correggono anche quell'inclinazione durante la revisione. Uno studio ha seguito diciannove atleti d'élite operati in questo modo.","Tutti sono tornati allo sport al livello di prima dell'infortunio, in circa un anno, con miglioramenti clinici netti e nessun nuovo fallimento del legamento nel follow-up, in media di quasi cinque anni.","Manca un gruppo di confronto con la sola revisione: non si può isolare quanto del merito sia della correzione dell'inclinazione. Un segnale incoraggiante su una strategia sempre più diffusa in chi ha già fallito una prima ricostruzione."],"pazienti":["Quando l'intervento di ricostruzione del legamento del ginocchio non tiene, in alcuni casi il chirurgo corregge anche la naturale inclinazione dell'osso della tibia, che può favorire un nuovo cedimento.","In un gruppo di diciannove sportivi d'élite operati con questa strategia, tutti sono tornati allo sport al livello di prima, in circa un anno, senza che il nuovo intervento cedesse di nuovo.","Manca però un confronto diretto con chi ha fatto solo la revisione: un risultato incoraggiante, non ancora una certezza, utile da conoscere per chi affronta un secondo intervento al legamento."]},"instagram":{"chir":["LCA fallito + slope ≥10°: revisione + osteotomia di riduzione dello slope in 19 atleti d'élite, 2 centri.","Rientro allo sport al 100%, IKDC 44→92, nessun fallimento dell'innesto a quasi 5 anni di follow-up medio.","Serie senza gruppo di confronto, livello IV: segnale forte, non ancora una dimostrazione comparativa."],"misto":["LCA fallito e tibia con inclinazione aumentata: alcuni centri correggono anche quella durante la revisione.","In 19 atleti d'élite: tutti tornati allo sport al livello pre-infortunio, nessun nuovo fallimento in quasi 5 anni.","Manca un confronto diretto con la sola revisione: segnale incoraggiante, non ancora una prova definitiva."],"pazienti":["Quando l'intervento al legamento del ginocchio non tiene, a volte si corregge anche la forma dell'osso della tibia.","In 19 sportivi d'élite operati così: tutti tornati allo sport come prima, nessun nuovo cedimento.","Manca un confronto con chi ha fatto solo la revisione: risultato incoraggiante da discutere col chirurgo."]},"reel":{"chir":["LCA fallito, slope aumentato: revisione più osteotomia, 19 atleti d'élite.","Tutti tornati in campo al livello di prima, nessun fallimento dell'innesto.","Serie senza confronto diretto: segnale forte, non ancora una dimostrazione."],"misto":["Quando il crociato rioperato ha anche una tibia più inclinata del normale.","Correggerla insieme alla revisione: tutti gli atleti tornati allo sport come prima.","Manca un confronto diretto: risultato incoraggiante, non ancora certo."],"pazienti":["Quando il legamento del ginocchio rioperato deve tenere meglio della prima volta.","Correggere anche la forma dell'osso della tibia ha aiutato 19 sportivi a tornare come prima.","Non è ancora un confronto diretto, ma un segnale incoraggiante per chi deve rioperarsi."]}},"4":{"video":{"chir":["Nell'osteotomia tibiale per correggere lo slope si può fissare l'osso con una placca metallica angolo-stabile oppure con una 'bioplacca' biodegradabile. Uno studio cadaverico su dodici ginocchia ha messo alla prova le due tecniche sotto carico ripetuto.","Nessuna differenza nel carico finale di rottura fra le due tecniche. Ma la bioplacca ha mostrato un micromovimento crescente durante il carico ciclico, assente con la placca metallica.","Gli stessi autori dichiarano di non poter concludere quale tecnica sia superiore, su soli sei campioni per gruppo e in donatori anziani. Non cambia la scelta della sintesi, ma il dato sul micromovimento va conosciuto."],"misto":["Quando si corregge chirurgicamente l'inclinazione della tibia, l'osteotomia si può fissare con una placca metallica oppure con una placca biodegradabile che il corpo riassorbe nel tempo. Uno studio di laboratorio ha confrontato le due tecniche sotto carichi ripetuti.","Il carico che ha rotto l'osso alla fine era simile fra le due tecniche. Ma la placca biodegradabile si è mossa un po' di più durante i carichi ripetuti, cosa che non è successa con quella metallica.","Gli autori stessi dicono di non poter dire quale tecnica sia migliore, con solo sei campioni per gruppo. Non cambia oggi la scelta della sintesi, ma è un'informazione tecnica utile per il futuro."],"pazienti":["Quando si corregge la forma dell'osso della tibia con un intervento, il pezzo d'osso tagliato va fissato: con una piccola placca metallica, oppure con una placca che il corpo assorbe da solo nel tempo.","Uno studio di laboratorio ha confrontato le due placche: la tenuta finale è risultata simile, ma quella che si riassorbe si è mossa un po' di più durante prove ripetute di carico.","È uno studio fatto su ossa di laboratorio, non su pazienti operati: un'informazione tecnica in più per il chirurgo, non una scoperta che cambia le cose oggi."]},"linkedin":{"chir":["Studio biomeccanico cadaverico, campioni appaiati (n=6/gruppo): ACW-HTO per correzione dello slope tibiale, fissazione trans-tuberosità 'bioplacca' vs infra-tuberosità angolo-stabile. 1000 cicli 50-200N a 1Hz, poi carico a rottura.","Nessuna differenza nel carico di rottura (643,9±190,8N vs 566,8±111,0N; p=0,422). Micromovimento crescente con bioplacca fra 200 e 800 cicli (0,055→0,069mm; p=0,025), assente con placca angolo-stabile.","Gli autori dichiarano esplicitamente: superiorità o inferiorità non concludibili con questo modello. Tu esegui correzioni di slope — il dato non cambia la scelta della sintesi, ma il micromovimento crescente della bioplacca va conosciuto."],"misto":["Nell'osteotomia per correggere l'inclinazione della tibia, l'osso tagliato si può fissare con una placca metallica oppure con una placca biodegradabile. Uno studio di laboratorio ha confrontato le due tecniche sotto carichi ripetuti su dodici ginocchia cadaveriche.","Il carico che alla fine ha rotto l'osso era simile fra le due tecniche. La placca biodegradabile però si è mossa progressivamente di più durante i cicli di carico ripetuto, cosa non osservata con quella metallica.","Gli stessi ricercatori dicono di non poter concludere quale tecnica sia migliore, con solo sei campioni per gruppo e donatori anziani. Non cambia oggi la pratica, ma è un dato tecnico utile per chi valuta impianti biodegradabili."],"pazienti":["Quando un intervento corregge la forma dell'osso della tibia, il pezzo d'osso tagliato va fissato con una piccola placca: metallica, oppure biodegradabile e riassorbita nel tempo dal corpo.","Uno studio di laboratorio ha confrontato le due soluzioni: la tenuta finale è risultata simile, ma la placca biodegradabile si è mossa un po' di più durante prove ripetute di carico.","È uno studio condotto su ossa di laboratorio, non su pazienti operati realmente: un'informazione tecnica per il chirurgo, non un cambiamento nella pratica di oggi."]},"instagram":{"chir":["ACW-HTO per correggere lo slope: bioplacca vs placca angolo-stabile, 12 ginocchia cadaveriche.","Carico di rottura simile, ma la bioplacca si muove di più sotto carico ciclico (p=0,025).","Autori: superiorità non concludibile con questo campione. Non cambia la scelta della sintesi oggi."],"misto":["Correggere l'inclinazione della tibia: placca metallica o biodegradabile per fissare l'osso?","In laboratorio, tenuta finale simile ma la placca biodegradabile si muove un po' di più nel tempo.","Studio piccolo, su donatori anziani: informazione tecnica utile, non ancora decisiva."],"pazienti":["Quando si corregge la forma dell'osso della tibia, il pezzo tagliato va fissato con una placca.","Uno studio di laboratorio mostra tenuta simile fra placca metallica e biodegradabile, con piccole differenze.","È un test di laboratorio, non su pazienti reali: informazione tecnica per il chirurgo."]},"reel":{"chir":["Slope osteotomy: bioplacca o placca metallica per fissare il taglio osseo?","Stesso carico di rottura, ma la bioplacca si muove di più sotto stress ripetuto.","Nessuna tecnica dimostrata superiore: dato tecnico, non un cambio di pratica."],"misto":["Correggere l'inclinazione della tibia: due modi di fissare l'osso tagliato.","Tenuta finale simile, ma la placca biodegradabile si muove un po' di più nel tempo.","Studio di laboratorio piccolo: informazione utile, non ancora decisiva."],"pazienti":["Quando si corregge la forma dell'osso della tibia, serve fissare il taglio con una placca.","Le due placche testate in laboratorio tengono in modo simile, con piccole differenze.","Non è ancora uno studio su pazienti reali, solo un test tecnico di laboratorio."]}},"5":{"video":{"chir":["Nella protesi di ginocchio si sta diffondendo la pianificazione personalizzata anche sul piano sagittale, non solo su quello frontale. Ma misurare la naturale inclinazione del femore prima dell'intervento, oggi, richiede quasi sempre una TC.","Uno studio ha testato un angolo semplice, misurabile su una radiografia laterale standard del ginocchio, confrontandolo con la misura di riferimento alla TC su quarantotto ginocchia.","L'accordo fra i due metodi è risultato molto forte, e la misura è riproducibile fra osservatori diversi. Un primo passo per portare la pianificazione sagittale nella pratica di routine, senza una TC dedicata."],"misto":["Quando si pianifica una protesi di ginocchio, oggi si guarda sempre di più anche all'inclinazione naturale del femore, non solo all'allineamento della gamba. Per misurarla di solito serve una TC.","Uno studio ha provato a misurare questa inclinazione su una semplice radiografia laterale del ginocchio, confrontando il risultato con quello della TC su quarantotto ginocchia.","Il risultato: le due misure si sono accordate molto bene, e la misura sulla radiografia è risultata affidabile anche ripetuta da persone diverse. Un passo verso una pianificazione più personalizzata senza bisogno di sempre una TC in più."],"pazienti":["Quando si pianifica una protesi di ginocchio, il chirurgo guarda anche alla forma naturale dell'osso del femore, per adattare l'intervento a ogni persona. Di solito questo richiede una TC in più.","Uno studio ha provato a misurare questa forma con una semplice radiografia, quella già fatta di routine, confrontandola con la TC su quasi cinquanta ginocchia.","Le due misure si sono accordate molto bene: un passo verso interventi pianificati su misura senza dover sempre aggiungere un esame in più come la TC."]},"linkedin":{"chir":["Studio retrospettivo di affidabilità, 44 pazienti/48 ginocchia con gonartrosi terminale: misura dell'angolo di flessione femorale nativa su radiografia laterale standard vs riferimento TC 3D automatizzato, per la pianificazione sagittale personalizzata in TKA.","Affidabilità intra/interosservatore eccellente (ICC 0,94 e 0,92); concordanza con la TC molto forte (ICC 0,86; IC 95% 0,77-0,92); bias medio 0,35°±0,9°, 95,9% dei casi entro 2° di differenza.","Riguarda ogni tua protesi totale, inclusa VELYS: oggi la pianificazione sagittale si basa quasi solo su TC o misure postoperatorie. Se confermato, questo metodo porterebbe la flessione femorale nativa nella radiografia preoperatoria di routine."],"misto":["Nella protesi di ginocchio si guarda sempre di più anche all'inclinazione naturale del femore, non solo all'asse della gamba, per personalizzare l'intervento. Misurarla oggi richiede quasi sempre una TC dedicata.","Uno studio ha misurato questo angolo su una radiografia laterale standard, già fatta di routine, confrontandolo con la TC su quarantotto ginocchia con artrosi avanzata.","L'accordo fra i due metodi è risultato molto forte e riproducibile fra osservatori diversi: un passo verso una pianificazione più su misura, senza aggiungere sempre un esame come la TC."],"pazienti":["Quando si pianifica una protesi di ginocchio, il chirurgo guarda anche alla forma naturale dell'osso del femore per adattare l'intervento alla persona. Questo di solito richiede una TC aggiuntiva.","Uno studio ha provato a misurare questa forma su una radiografia semplice, quella già fatta di routine, confrontandola con la TC su quasi cinquanta ginocchia con artrosi avanzata.","Le due misure si sono accordate molto bene: un passo verso protesi pianificate su misura, senza dover sempre aggiungere un esame come la TC."]},"instagram":{"chir":["Flessione femorale nativa: misurabile su radiografia laterale standard? 44 pazienti/48 ginocchia con gonartrosi terminale.","ICC vs TC 0,86 (IC 95% 0,77-0,92), affidabilità intra/interosservatore eccellente (0,94/0,92).","Utile per la pianificazione sagittale personalizzata in ogni protesi, anche VELYS, senza TC dedicata."],"misto":["Anche la forma naturale del femore conta nella pianificazione della protesi di ginocchio.","Uno studio mostra che si può misurare bene su una radiografia laterale standard, non solo con la TC.","Accordo molto forte fra i due metodi: un passo verso protesi pianificate su misura più semplicemente."],"pazienti":["Anche la forma naturale dell'osso del femore conta quando si pianifica una protesi di ginocchio.","Uno studio mostra che si può misurare su una radiografia semplice, senza sempre servire una TC.","Un passo verso interventi pianificati su misura in modo più semplice per il paziente."]},"reel":{"chir":["La flessione femorale nativa si misura anche su una radiografia laterale, non solo alla TC.","Accordo molto forte con la TC su quasi 50 ginocchia con artrosi avanzata.","Utile per la pianificazione sagittale in ogni protesi, anche robotica."],"misto":["Anche la forma naturale del femore conta nella protesi di ginocchio.","Si può misurare su una radiografia semplice, non serve sempre la TC.","Un passo verso protesi più su misura, in modo più semplice."],"pazienti":["Pianificare la protesi di ginocchio guardando anche alla forma naturale del femore.","Bastano radiografie standard, non serve sempre una TC in più.","Un passo verso interventi su misura, più semplici per il paziente."]}},"6":{"video":{"chir":["L'instabilità in flessione dopo protesi postero-stabilizzata è una causa di insoddisfazione spesso sottodiagnosticata. Uno studio su centoquarantacinque ginocchia ha testato due strumenti clinici per riconoscerla meglio.","La radiografia sotto carico in ginocchio e il segno del cassetto posteriore si sono associati in modo indipendente all'instabilità riferita dal paziente. Il classico test del cassetto anteriore a novanta gradi, invece, non ha discriminato nulla.","La capacità discriminante della radiografia sotto carico resta però solo modesta. Due strumenti in più da usare insieme all'esame clinico, non al suo posto."],"misto":["Dopo una protesi di ginocchio, alcuni pazienti sentono l'articolazione poco stabile quando la piegano, un problema spesso difficile da riconoscere con i test classici. Uno studio ha provato due strumenti su centoquarantacinque ginocchia protesizzate.","Una radiografia fatta mettendosi in ginocchio sotto carico, insieme a un segno rilevabile alla visita, si sono associati davvero a questa instabilità riferita dal paziente. Il test classico, invece, non ha aiutato a distinguere.","La capacità di questi strumenti di distinguere resta però solo modesta: utili in più, non da soli, insieme alla valutazione clinica completa del chirurgo."],"pazienti":["Dopo una protesi di ginocchio, alcune persone sentono l'articolazione poco sicura quando la piegano, un problema che a volte è difficile da individuare con la sola visita.","Uno studio ha provato due strumenti in più per riconoscerlo meglio: una radiografia fatta inginocchiandosi sotto peso, e un segno che il medico può cercare durante la visita.","Questi strumenti aiutano, ma non bastano da soli a essere sicuri: restano un aiuto in più per il medico, insieme alla visita completa."]},"linkedin":{"chir":["Coorte retrospettiva, 145 ginocchia PS-TKA/119 pazienti (30 con instabilità soggettiva in flessione, 20,7%): kneeling stress radiography (Δ-TPFA) e posterior sag sign confrontati col cassetto anteriore a 90°.","Δ-TPFA 1,40±3,75mm (instabili) vs -1,17±3,28mm (stabili); p=0,001, AUC 0,68, predittore indipendente (OR 1,30/mm). Posterior sag sign: specificità 82,6%, OR 3,26. Cassetto anteriore a 90°: non discriminante (p=0,41).","Riguarda ogni tua protesi postero-stabilizzata: due strumenti diagnostici in più per l'instabilità in flessione, ma con discriminazione solo modesta (AUC 0,68) — da integrare con l'esame clinico, non da sostituirlo."],"misto":["Alcuni pazienti, dopo una protesi di ginocchio, riferiscono un senso di instabilità quando piegano il ginocchio — un problema spesso sottovalutato e difficile da confermare con i test classici.","Uno studio su centoquarantacinque ginocchia protesizzate mostra che una radiografia fatta sotto carico da inginocchiati, insieme a un segno rilevabile durante la visita, si associano davvero a questa instabilità. Il test classico del cassetto a novanta gradi, invece, non ha aiutato a distinguere i due gruppi.","La capacità di questi strumenti di riconoscere davvero l'instabilità resta però modesta: sono un aiuto in più per il chirurgo, da usare insieme alla visita clinica completa, non al posto di essa."],"pazienti":["Dopo una protesi di ginocchio, alcune persone sentono l'articolazione poco sicura quando la piegano — un problema a volte difficile da riconoscere con la sola visita.","Uno studio su centoquarantacinque ginocchia protesizzate ha provato due strumenti in più: una radiografia fatta inginocchiandosi sotto peso, e un segno che il medico può cercare durante la visita, entrambi collegati a questo disturbo.","Questi strumenti aiutano, ma non bastano da soli per essere certi: restano un supporto in più per il chirurgo, insieme a una visita completa."]},"instagram":{"chir":["Instabilità in flessione dopo TKA postero-stabilizzata: 145 ginocchia, kneeling stress radiography + posterior sag sign.","Δ-TPFA predittore indipendente (OR 1,30/mm, AUC 0,68); posterior sag sign specificità 82,6%. Cassetto a 90° non discrimina.","Strumenti in più, discriminazione solo modesta: da usare insieme all'esame clinico, non al suo posto."],"misto":["A volte dopo la protesi di ginocchio l'articolazione sembra poco stabile quando si piega: difficile da confermare con i test soliti.","Una radiografia sotto carico da inginocchiati e un segno alla visita aiutano a riconoscerlo meglio, su 145 ginocchia protesizzate.","Capacità discriminante solo modesta: strumenti in più, non sostituti della visita clinica."],"pazienti":["Dopo una protesi di ginocchio, a volte l'articolazione sembra poco sicura quando si piega.","Due strumenti in più aiutano il medico a riconoscerlo meglio: una radiografia particolare e un segno alla visita.","Non bastano da soli: restano un aiuto, insieme a una visita completa."]},"reel":{"chir":["Instabilità in flessione dopo TKA postero-stabilizzata: spesso sottodiagnosticata.","Due strumenti in più per riconoscerla, il test classico non basta.","Discriminazione solo modesta: da integrare con l'esame clinico."],"misto":["A volte, dopo la protesi, il ginocchio sembra poco stabile quando si piega.","Una radiografia particolare e un segno alla visita aiutano a capirlo meglio.","Non bastano da soli: un aiuto in più per il chirurgo."],"pazienti":["Dopo una protesi, a volte il ginocchio sembra poco sicuro quando si piega.","Due strumenti in più aiutano il medico a capire perché.","Restano un aiuto, non sostituiscono la visita completa."]}}};
var TAGS={"1":{"linkedin":"#ACLReconstruction #KneeSurgery #SportsMedicine","instagram":"#LCA #Ginocchio #Ortopedia #ChirurgiaOrtopedica #MedicinaSportiva #LET #RicostruzioneLegamento #Ricerca #SaluteDelGinocchio","kw":"rinforzo laterale LCA, tenodesi extra-articolare ginocchio"},"2":{"linkedin":"#MPFL #PediatricOrthopedics #PatellarInstability","instagram":"#MPFL #Rotula #Ginocchio #Ortopedia #ChirurgiaPediatrica #InstabilitaRotulea #MedicinaSportiva #Ricerca #SaluteDelGinocchio","kw":"instabilita rotula adolescente, ricostruzione MPFL bambini"},"3":{"linkedin":"#ACLRevision #SlopeCorrection #SportsMedicine","instagram":"#LCA #Osteotomia #Ginocchio #Ortopedia #RevisioneLCA #SlopeTibiale #MedicinaSportiva #Ricerca #SaluteDelGinocchio","kw":"revisione LCA slope tibiale, osteotomia riduzione slope"},"4":{"linkedin":"#HTO #KneeOsteotomy #Biomechanics","instagram":"#Osteotomia #Ginocchio #Ortopedia #SlopeTibiale #Biomeccanica #ChirurgiaOrtopedica #MedicinaSportiva #Ricerca #SaluteDelGinocchio","kw":"fissazione osteotomia tibiale, bioplacca vs placca metallica"},"5":{"linkedin":"#TKA #RoboticKnee #SurgicalPlanning","instagram":"#ProtesiGinocchio #Ortopedia #ChirurgiaOrtopedica #PianificazionePersonalizzata #Robotica #ArtrosiGinocchio #Ricerca #SaluteDelGinocchio #Radiologia","kw":"pianificazione protesi ginocchio, flessione femorale radiografia"},"6":{"linkedin":"#TKA #FlexionInstability #KneeArthroplasty","instagram":"#ProtesiGinocchio #Ortopedia #ChirurgiaOrtopedica #InstabilitaGinocchio #ArtrosiGinocchio #Diagnostica #MedicinaSportiva #Ricerca #SaluteDelGinocchio","kw":"instabilita flessione protesi ginocchio, protesi postero-stabilizzata"}};
var NLB={"1":{"prof":["Il LET aggiunto alla ACLR: più artrofibrosi e artrosi codificata su oltre 10.000 pazienti","Coorte propensity-matched su TriNetX (5021+5021): con il LET più procedure per artrofibrosi a 1 anno (OR 1,65), più chirurgia meniscale a 2 anni (HR 1,25) e più artrosi codificata a 5 anni (HR 2,24), senza riduzione della nuova ACLR.","Dati amministrativi, nessuna stratificazione per innesto o costrutto del LET, confondimento per indicazione plausibile: non chiude la domanda sul tuo innesto rigido, ma è il primo bilancio reale sui costi del gesto."],"mix":["Il rinforzo laterale (LET) aggiunto al crociato anteriore: un grande studio pesa anche i costi","Su oltre diecimila pazienti di un database assicurativo americano, chi riceve il LET insieme alla ricostruzione del crociato ha più interventi per rigidità del ginocchio, più chirurgia sul menisco negli anni dopo e più diagnosi di artrosi a cinque anni, senza un chiaro vantaggio sul reintervento.","È uno studio osservazionale su dati assicurativi, non un confronto clinico diretto, e non distingue il tipo di innesto: un limite importante prima di trarre conclusioni definitive, ma un segnale che vale la pena conoscere."],"paz":["Un gesto spesso aggiunto quando si ricostruisce il legamento del ginocchio: cosa dice un grande studio","Quando si ricostruisce il legamento crociato del ginocchio, si aggiunge spesso un piccolo gesto su un lato dell'articolazione per renderla più stabile nei movimenti di torsione. Un ampio studio americano mostra che chi lo riceve ha avuto più spesso bisogno di un intervento per rigidità e più interventi sul menisco negli anni successivi.","Non è una prova definitiva — è uno studio osservazionale, non un confronto diretto — ma è un'informazione utile da discutere serenamente con il proprio chirurgo prima dell'intervento."],"kw":"rinforzo laterale ginocchio, LET ricostruzione crociato anteriore"},"2":{"prof":["MPFL pediatrico: il tunnel osseo tiene più dell'ancora a sutura, in laboratorio","Studio cadaverico su 10 rotule pediatriche: carico di rottura molto più alto con tunnel osseo (169,8±88,6N) che con ancora a sutura (55,3±20,1N; p=0,002); rigidità sovrapponibile, ma su soli 5 campioni per gruppo.","Test a tempo zero, senza carico ciclico né guarigione in vivo, un solo modello di ancora testato: un segnale biomeccanico, non ancora una ragione per cambiare tecnica al di fuori dell'adolescente a rischio."],"mix":["Fissare l'MPFL nei più giovani: un tunnel nell'osso tiene più di un'ancora, mostra uno studio","Uno studio di laboratorio su rotule pediatriche di cadavere ha confrontato due modi di fissare il legamento che stabilizza la rotula: con una piccola ancora a sutura oppure con un tunnel scavato nell'osso. Il tunnel ha retto un carico quasi tre volte più alto prima di cedere.","È un test di laboratorio, su un campione piccolo e senza carico ripetuto nel tempo: un segnale utile per la scelta della fissazione nei pazienti più giovani, non ancora una dimostrazione clinica."],"paz":["Rotula instabile nei ragazzi: come si fissa il legamento che la trattiene","Quando la rotula di un adolescente esce spesso dal suo posto, si ricostruisce un piccolo legamento interno (MPFL) fissandolo sulla rotula con una piccola ancora oppure con un tunnel nell'osso. Uno studio di laboratorio su rotule di bambini mostra che il tunnel nell'osso regge di più prima di cedere.","È un test fatto in laboratorio, non uno studio su pazienti operati davvero: un'informazione tecnica in più che il chirurgo può usare per scegliere la fissazione più adatta nei ragazzi più giovani."],"kw":"MPFL rotula bambini, ricostruzione legamento patello-femorale"},"3":{"prof":["Slope aumentato e LCA fallito: l'osteotomia con la revisione rimette in campo tutti gli atleti","Serie di 19 atleti d'élite, 2 centri: revisione ACLR + osteotomia di riduzione dello slope, rientro allo sport al 100% (media 12,1 mesi), IKDC 44,2→92,3, nessun fallimento dell'innesto a follow-up medio di quasi 5 anni.","Serie a braccio unico, livello IV: non isola l'effetto dell'osteotomia da quello della revisione. Un segnale diretto, non ancora una dimostrazione comparativa."],"mix":["Crociato rioperato e tibia più inclinata: correggerla insieme aiuta a tornare allo sport","In diciannove atleti d'élite con una ricostruzione del legamento crociato fallita e un'inclinazione naturale della tibia più marcata, correggere anche l'inclinazione durante la revisione ha permesso a tutti di tornare allo sport al livello di prima, senza nuovi cedimenti in quasi cinque anni di controllo.","Manca un gruppo di confronto operato con la sola revisione, ed è un campione piccolo (diciannove pazienti): un risultato incoraggiante su una strategia sempre più discussa, non ancora una dimostrazione definitiva del beneficio aggiuntivo."],"paz":["Quando il legamento del ginocchio rioperato deve tenere meglio della prima volta","In alcuni pazienti che hanno già fallito una prima ricostruzione del legamento crociato, il chirurgo corregge anche la naturale inclinazione dell'osso della tibia, che può favorire un nuovo cedimento. In un gruppo di diciannove sportivi d'élite operati così, tutti sono tornati allo sport come prima, senza problemi nel tempo.","Manca un confronto diretto con chi ha fatto solo la revisione: un risultato incoraggiante, non ancora una certezza assoluta, utile da conoscere e discutere con il proprio chirurgo."],"kw":"osteotomia slope revisione LCA, correzione slope tibiale ginocchio"},"4":{"prof":["Osteotomia per lo slope: la bioplacca si muove di più sotto carico ciclico, non alla rottura","Studio cadaverico, 12 ginocchia appaiate: nessuna differenza nel carico di rottura fra bioplacca e placca angolo-stabile (643,9±190,8N vs 566,8±111,0N; p=0,422), ma micromovimento crescente con bioplacca durante il carico ciclico (p=0,025).","Solo 6 campioni per gruppo, donatori anziani, test a tempo zero: gli stessi autori dichiarano di non poter concludere sulla superiorità di una tecnica."],"mix":["Correggere l'inclinazione della tibia: due modi di fissare l'osso, un piccolo studio li confronta","Quando si corregge chirurgicamente l'inclinazione della tibia, l'osso tagliato si fissa con una placca metallica oppure con una biodegradabile. In laboratorio, la tenuta finale è risultata simile, ma la placca biodegradabile si è mossa progressivamente di più durante prove di carico ripetuto.","È uno studio su un campione piccolo, sole dodici ginocchia di donatori anziani, e gli stessi ricercatori dicono di non poter concludere quale tecnica sia migliore: un dato tecnico, non ancora una risposta definitiva."],"paz":["Correggere la forma dell'osso della tibia: come si fissa il taglio chirurgico","Quando un intervento corregge la forma dell'osso della tibia, il pezzo tagliato va fissato con una piccola placca, che può essere metallica oppure biodegradabile e assorbita dal corpo nel tempo. Un test di laboratorio mostra una tenuta simile fra le due, con piccole differenze nel tempo.","È uno studio condotto su ossa di laboratorio, non su pazienti operati davvero: un'informazione tecnica in più per il chirurgo, non una novità che cambia le cose per chi deve operarsi oggi."],"kw":"osteotomia tibiale slope, fissazione bioplacca ginocchio"},"5":{"prof":["La flessione femorale nativa si misura bene anche su radiografia standard del ginocchio","Studio di affidabilità, 44 pazienti/48 ginocchia: ICC intra/interosservatore 0,94 e 0,92; concordanza con la TC molto forte (ICC 0,86; IC 95% 0,77-0,92), bias medio 0,35°±0,9°.","Livello IV, un solo metodo testato, popolazione con gonartrosi terminale: un passo verso la pianificazione sagittale di routine, non ancora una validazione su ogni grado di artrosi."],"mix":["Protesi di ginocchio su misura: anche la forma naturale del femore si può misurare senza TC","Uno studio ha confrontato una misura semplice, fatta su una radiografia laterale standard del ginocchio già eseguita di routine, con la misura di riferimento alla TC, su quasi cinquanta ginocchia con artrosi avanzata: l'accordo fra le due è risultato molto forte.","È uno studio retrospettivo su un solo metodo di misura e un campione piccolo (48 ginocchia), in pazienti con artrosi già avanzata: un passo promettente verso una pianificazione più personalizzata, non ancora una validazione su ogni caso."],"paz":["Pianificare la protesi di ginocchio guardando anche alla forma naturale del femore","Quando si pianifica una protesi di ginocchio, il chirurgo considera anche la forma naturale dell'osso del femore. Di solito questo richiede una TC in più; uno studio mostra che si può misurare bene anche su una radiografia semplice, di quelle già fatte di routine.","È uno studio su un gruppo di pazienti con artrosi già avanzata, non ancora validato in ogni situazione: un passo promettente verso interventi pianificati su misura in modo più semplice."],"kw":"protesi ginocchio pianificazione personalizzata, flessione femorale radiografia"},"6":{"prof":["Instabilità in flessione dopo TKA postero-stabilizzata: due strumenti in più, discriminazione modesta","Coorte di 145 ginocchia/119 pazienti: Δ-TPFA su radiografia sotto carico predittore indipendente (OR 1,30/mm; AUC 0,68), posterior sag sign specificità 82,6% (OR 3,26); il cassetto anteriore a 90° non discrimina (p=0,41).","Studio monocentrico, discriminazione solo modesta (AUC 0,68), instabilità soggettiva come esito: strumenti da integrare con l'esame clinico, non da sostituirlo."],"mix":["Ginocchio poco stabile dopo la protesi: due strumenti in più per capire perché","In alcuni pazienti, dopo una protesi di ginocchio postero-stabilizzata, resta un senso di instabilità quando si piega l'articolazione — un problema spesso sottovalutato. Uno studio su centoquarantacinque ginocchia mostra che una radiografia particolare fatta sotto carico e un segno rilevabile alla visita aiutano davvero a riconoscerlo, meglio del test classico.","È uno studio su un singolo centro, con un campione piccolo di ginocchia instabili (trenta): la capacità di questi strumenti di distinguere resta solo modesta, come dichiarano gli stessi autori — un aiuto in più per il chirurgo, non un sostituto della valutazione clinica completa."],"paz":["Perché il ginocchio protesizzato a volte sembra poco stabile quando si piega","Dopo una protesi di ginocchio, alcune persone sentono l'articolazione poco sicura nei movimenti di flessione, un problema che il medico può faticare a confermare con la sola visita. Uno studio propone due strumenti in più — una radiografia particolare e un segno rilevabile alla visita — per riconoscerlo meglio.","Questi strumenti aiutano ma non bastano da soli: restano un supporto in più per il chirurgo, insieme a una visita clinica completa, senza sostituirla."],"kw":"instabilita ginocchio dopo protesi, protesi ginocchio postero-stabilizzata"}};
var ARTICLES=[{n:1,mono:"m-kssta",dot:"orange",sec:"res",j:"Knee Surgery, Sports Traumatology, Arthroscopy",h:"Il rinforzo laterale aggiunto al LCA aumenta artrofibrosi e artrosi",v:"Coorte propensity-matched su oltre diecimila pazienti (database TriNetX): con il LET più interventi per artrofibrosi, più chirurgia meniscale successiva e più artrosi codificata a 5 anni, senza una riduzione dimostrata della nuova ricostruzione.",ax:"Rteil, Jason Koh, Amirouche",date:"set 2026",meta:"coorte retrospettiva propensity-matched (TriNetX), 5021+5021 · [III]",pmid:'42731122',doi:'10.1002/ksa.70600',journal:"Knee Surgery, Sports Traumatology, Arthroscopy",authors:"Rteil A, Jason K, Amirouche F",design:"Studio retrospettivo di coorte sul database claims TriNetX. Pazienti sottoposti a ricostruzione primaria del LCA isolata o con l'aggiunta di una tenodesi extra-articolare laterale (LET), identificati per codice CPT, appaiati 1:1 per propensity score. Esiti precoci (3-6 mesi): procedure per artrofibrosi, complicanze di ferita, uso di oppioidi, utilizzo di riabilitazione, accessi in pronto soccorso, riospedalizzazioni. Esiti a 1-2 anni: nuova ACLR, chirurgia meniscale successiva. Esito a 5 anni: artrosi di ginocchio codificata (ICD). Sottogruppo 12-25 anni analizzato separatamente.",pop:"5021 pazienti per braccio dopo il matching (10.042 in totale); nessuna descrizione di innesto o tecnica di LET riportata nell'abstract — il confronto è ACLR isolata contro ACLR+LET indipendentemente dal tipo di innesto o dal costrutto del LET.",results:"A 1 anno più procedure per artrofibrosi con il LET (3,4% contro 2,1%; OR 1,65; IC 95% 1,29-2,11; p<0,001); a 2 anni più chirurgia meniscale successiva (HR 1,25; p<0,05) e nessuna differenza sulla nuova ACLR; a 5 anni più artrosi di ginocchio codificata (HR 2,24; IC 95% 1,76-2,85; p<0,001), confermata anche nell'analisi landmark a 1 anno (HR 2,57; p<0,001). Nel sottogruppo 12-25 anni, il LET si associa a minori probabilità di una nuova ACLR a 1 anno.",concl:"Gli autori concludono che il LET si associa a maggiore morbidità postoperatoria precoce, a maggiori interventi meniscali successivi e a maggiore artrosi codificata a 5 anni, senza una riduzione dimostrabile della ricostruzione successiva nell'analisi primaria a 2 anni; raccomandano una selezione e un colloquio attenti prima di aggiungere il LET, dichiarando esplicitamente che si tratta di associazioni, non di effetti causali dimostrati, per il disegno retrospettivo e il possibile confondimento per indicazione.",limits:"Dati amministrativi (codici CPT/ICD), non misure cliniche dirette di lassità o forza · nessuna stratificazione per tipo di innesto né per costrutto del LET (onlay o profondo, Lemaire o altro): non risponde alla domanda specifica sull'innesto rigido di questa tensione · confondimento per indicazione plausibile — chi riceve il LET può essere selezionato proprio perché a rischio più alto, non è detto che il LET lo crei.",perte:"È il primo bilancio su scala reale — oltre diecimila pazienti — dei costi del gesto che esegui su ogni paziente operato di LCA, non solo dei suoi benefici. Non isola il tuo innesto né il tuo costrutto (onlay superficiale), e il segnale nel sottogruppo giovane va nella direzione opposta a quello generale: non chiude la tensione sull'innesto rigido, apre però per la prima volta un conto sul lato dei rischi del LET universale."},{n:2,mono:"m-ojsm",dot:"orange",sec:"res",j:"Orthopaedic Journal of Sports Medicine",h:"Nella rotula pediatrica il tunnel osseo tiene più dell'ancora a sutura per l'MPFL",v:"Studio cadaverico su dieci rotule pediatriche: la fissazione con tunnel osseo regge un carico di rottura molto più alto di quella con ancora a sutura, con lo stesso meccanismo di cedimento — sfilamento dell'ancora — in ogni caso testato.",ax:"Khoo, Baird, Alawa et al.",date:"set 2026",meta:"studio cadaverico pediatrico, 10 rotule/6 donatori · [V]",pmid:'42729516',doi:'10.1177/23259671261465205',journal:"Orthopaedic Journal of Sports Medicine",authors:"Khoo B, Baird HBG, Alawa J, Alayleh A, Johnstone T, Chan C, Shea KG",design:"Studio di laboratorio controllato. Dieci rotule cadaveriche pediatriche (sei donatori, 9-11 anni) allocate a fissazione patellare per la ricostruzione dell'MPFL con due ancore a sutura da 1,8 mm oppure con due tunnel ossei da 2 mm e sutura intrecciata. Test di carico a rottura su macchina servomeccanica, direzione di trazione allineata all'inserzione nativa dell'MPFL.",pop:"10 rotule cadaveriche pediatriche da 6 donatori (3 maschi, 3 femmine), età media 9,8 anni (9-11).",results:"Carico di rottura significativamente più alto con tunnel osseo (169,8±88,6 N) che con ancora a sutura (55,3±20,1 N; p=0,002); rigidità del costrutto sovrapponibile fra le due tecniche (6±1,9 contro 6,4±1,7 N/mm; p=0,647). Meccanismo di cedimento: sfilamento dell'ancora per tutte le ancore, taglio della sutura nell'osso per tutti i tunnel.",concl:"Gli autori concludono che, in questo modello pediatrico, la fissazione a tunnel osseo regge un carico iniziale più alto dell'ancora a sutura, e propongono di considerare tunnel obliqui di piccolo diametro nei pazienti con bassa densità ossea per ridurre il rischio di cedimento della fissazione patellare.",limits:"Test a tempo zero, nessun carico ciclico né guarigione in vivo · un solo modello di ancora a sutura testato, non generalizzabile a ogni sistema in commercio · rigidità sovrapponibile con soli 5 campioni per gruppo: un campione minuscolo, non una dimostrazione di equivalenza.",perte:"Tu fissi l'MPFL con ancore FiberTak in tecnica onlay, e operi anche pazienti dai 14 anni. Questo è il primo dato biomeccanico specifico sulla rotula pediatrica che confronta ancora e tunnel osseo, e il risultato non va nella direzione della fissazione ad ancora: un segnale da tenere presente nella scelta della fissazione nell'adolescente con bassa densità ossea, non ancora una ragione per cambiare tecnica negli altri pazienti."},{n:3,mono:"m-gray",dot:"green",sec:"res",j:"The American Journal of Sports Medicine",h:"L'osteotomia per ridurre lo slope, con la revisione del LCA, rimette in campo gli atleti d'élite",v:"Serie di 19 atleti d'élite con slope tibiale aumentato e LCA fallito: tutti tornano al livello pre-infortunio dopo revisione combinata con osteotomia di riduzione dello slope, nessun fallimento dell'innesto.",ax:"Martorell-de Fortuny, Perelli, Cance et al.",date:"set 2026",meta:"serie di casi, 19 atleti d'élite, 2 centri · [IV]",pmid:'42728689',doi:'10.1177/03635465261479920',journal:"The American Journal of Sports Medicine",authors:"Martorell-de Fortuny L, Perelli S, Cance N, Mazy D, Monllau JC, Dejour DH",design:"Serie di casi retrospettiva, due centri (Barcellona e Lione). Atleti d'élite con LCA fallito e slope tibiale posteriore ≥10 gradi, operati fra il 2011 e il 2023 di revisione del LCA combinata con osteotomia sovratuberositaria di riduzione dello slope. Esiti: tasso e tempo di rientro allo sport, punteggi clinici e funzionali (IKDC, Lysholm, Tegner, ACL-RSI), parametri radiografici (slope tibiale, asse anca-ginocchio-caviglia, indice di Caton-Deschamps).",pop:"22 interventi eseguiti, 19 pazienti inclusi nell'analisi; follow-up medio 58,8 mesi (24-169).",results:"Rientro in campo al livello pre-infortunio nel 100% dei casi, dopo una media di 12,1 mesi (10-20); ACL-RSI medio 87,2. IKDC da 44,2 a 92,3 (IC 95% 42-54; p<0,001); Lysholm da 46,8 a 96,9 (IC 95% 35,2-65; p<0,001); Tegner postoperatorio medio 9,7. Slope tibiale medio da 14,9° a 4,5°, senza cambiamenti significativi dell'asse coronale o dell'altezza rotulea. Nessun fallimento dell'innesto; unico reintervento la rimozione di una graffa per fastidio locale.",concl:"Gli autori concludono che, in atleti d'élite con slope aumentato e LCA già fallito, combinare l'osteotomia di riduzione dello slope con la revisione del LCA è sicuro ed efficace, permettendo il rientro allo sport al livello pre-infortunio con ottimi risultati clinici e funzionali.",limits:"Serie di casi a braccio unico, senza un gruppo di confronto con la sola revisione del LCA: non si può attribuire il risultato all'osteotomia aggiunta piuttosto che alla revisione in sé · livello di evidenza IV, dichiarato dagli stessi autori · popolazione altamente selezionata (atleti d'élite, due centri di riferimento per lo slope), non generalizzabile al paziente comune.",perte:"Tu esegui correzioni di slope nella tua pratica di osteotomie. Questa serie, per quanto senza gruppo di controllo, è uno dei segnali più diretti finora sull'associare la correzione dello slope alla revisione del LCA in un profilo di paziente ad alto rischio di re-fallimento — utile nel colloquio con l'atleta che ha già fallito una ricostruzione e ha uno slope aumentato."},{n:4,mono:"m-jeo",dot:"green",sec:"res",j:"Journal of Experimental Orthopaedics",h:"Nell'osteotomia per lo slope la placca biodegradabile si muove di più sotto carico ciclico",v:"Studio cadaverico su 12 ginocchia: la 'bioplacca' in materiale biodegradabile mostra più micromovimento durante il carico ciclico della placca metallica angolo-stabile, ma senza differenza nel carico di rottura finale.",ax:"Jasina, Metje, Sass et al.",date:"set 2026",meta:"studio cadaverico, 12 ginocchia appaiate · [V]",pmid:'42730384',doi:'10.1002/jeo2.70911',journal:"Journal of Experimental Orthopaedics",authors:"Jasina A, Metje P, Sass JO, Hembus J, Simons S, Gräber S, Liebau K, Bader R, Schuster P, Kebbach M, Pourostad P, Lutter C, Ferner F",design:"Studio biomeccanico cadaverico, campioni appaiati per donatore. Confronto fra fissazione trans-tuberosità con 'bioplacca' e fissazione infra-tuberosità con placca angolo-stabile dopo osteotomia tibiale alta a cuneo di chiusura anteriore per la correzione dello slope tibiale posteriore. Precarico, poi 1000 cicli fra 50 e 200 N a 1 Hz, poi carico a rottura a 10 mm/s. Micromovimento al focolaio misurato con sistema ottico 3D dopo 200 e 800 cicli.",pop:"12 ginocchia cadaveriche fresche-congelate (6 per gruppo, donatori appaiati), età media 79,2 anni.",results:"Nessuna differenza significativa di micromovimento fra i due gruppi né dopo 200 cicli (p=0,515) né dopo 800 (p=0,889); nel gruppo bioplacca il micromovimento aumenta da 0,055±0,017 mm a 0,069±0,035 mm fra 200 e 800 cicli (p=0,025), aumento assente con la placca angolo-stabile (p=0,518). Carico di rottura sovrapponibile (643,9±190,8 N contro 566,8±111,0 N; p=0,422).",concl:"Gli autori concludono che non è stata rilevata una differenza significativa nel carico di rottura fra le due tecniche, ma la bioplacca mostra un aumento del micromovimento durante il carico ciclico; dichiarano esplicitamente che, nei limiti del modello biomeccanico, la superiorità o l'inferiorità di una tecnica sull'altra non può essere conclusa.",limits:"Solo 6 campioni per gruppo, donatori anziani (media 79 anni), lontani dal profilo tipico del paziente operato di slope · test a tempo zero/carico ciclico limitato, nessuna guarigione ossea reale · gli stessi autori dichiarano di non poter concludere sulla superiorità di una tecnica.",perte:"Tu esegui osteotomie di correzione dello slope. Il dato non cambia la scelta della sintesi — nessuna differenza dimostrata nel carico di rottura — ma il micromovimento crescente con la bioplacca sotto carico ciclico è un elemento da conoscere se mai si valutasse un impianto biodegradabile per questo tipo di osteotomia."},{n:5,mono:"m-gray",dot:"green",sec:"res",j:"Orthopaedics & Traumatology: Surgery & Research",h:"La flessione femorale nativa si misura bene anche su una radiografia standard del ginocchio",v:"Studio di affidabilità su 48 ginocchia: un angolo semplice, misurato su una radiografia laterale standard, concorda fortemente con la misura di riferimento alla TC — un passo verso la pianificazione sagittale personalizzata in protesi.",ax:"Giurazza, Perrier, Tessier et al.",date:"set 2026",meta:"studio di affidabilità, coorte retrospettiva, 44 pazienti/48 ginocchia · [IV]",pmid:'42731810',doi:'10.1016/j.otsr.2026.104874',journal:"Orthopaedics & Traumatology: Surgery & Research",authors:"Giurazza G, Perrier A, Tessier V, Graff W, Marmor S, Mouton A, Aubert T",design:"Studio retrospettivo di affidabilità. In pazienti con gonartrosi in fase avanzata candidati a protesi totale, misura dell'angolo di flessione femorale nativa su radiografia laterale standard del ginocchio (fra l'asse diafisario distale del femore e l'asse meta-epifisario) confrontata con una misura automatizzata equivalente su TC 3D. Affidabilità intra e interosservatore con coefficiente di correlazione intraclasse (ICC) e analisi di Bland-Altman.",pop:"44 pazienti, 48 ginocchia con gonartrosi in stadio terminale.",results:"Angolo di flessione femorale radiografico medio 2,5°±1,84° (range -2,1° a 6,9°). Affidabilità intra e interosservatore eccellente (ICC 0,94 e 0,92). Concordanza fra misura radiografica e riferimento TC molto forte (ICC 0,86; IC 95% 0,77-0,92); bias medio all'analisi di Bland-Altman 0,35°±0,9°, con il 95,9% dei casi entro 2° di differenza fra i due metodi.",concl:"Gli autori concludono che la flessione femorale nativa si può misurare in modo affidabile su una semplice radiografia laterale standard del ginocchio, con un metodo riproducibile e in forte accordo con la TC — un passo verso l'integrazione sistematica del piano sagittale nella pianificazione personalizzata della protesi di ginocchio.",limits:"Studio retrospettivo, livello di evidenza IV dichiarato dagli stessi autori · un solo metodo di misura radiografica testato, non confrontato con altre tecniche pubblicate · popolazione con gonartrosi terminale: la validità nei gradi meno avanzati non è verificata.",perte:"Riguarda ogni tua protesi totale di ginocchio, inclusa quella con VELYS: oggi la pianificazione sagittale personalizzata si basa quasi solo su TC o su misure postoperatorie; questo metodo, se confermato, permetterebbe di conoscere la flessione femorale nativa già dalla radiografia preoperatoria di routine, senza una TC dedicata."},{n:6,mono:"m-gray",dot:"green",sec:"res",j:"Archives of Orthopaedic and Trauma Surgery",h:"Il segno del cassetto posteriore in flessione aiuta a riconoscere l'instabilità dopo protesi",v:"Coorte di 145 ginocchia con protesi postero-stabilizzata: la radiografia sotto carico e il segno del cassetto posteriore aiutano a riconoscere l'instabilità in flessione riferita dal paziente, ma con una discriminazione solo modesta.",ax:"Aşkın, Çağlar, Tokgözoğlu, Atilla",date:"set 2026",meta:"coorte retrospettiva, 145 ginocchia/119 pazienti · [III]",pmid:'42728442',doi:'10.1007/s00402-026-06448-4',journal:"Archives of Orthopaedic and Trauma Surgery",authors:"Aşkın M, Çağlar Ö, Tokgözoğlu AM, Atilla B",design:"Studio retrospettivo comparativo. Pazienti operati di protesi totale di ginocchio postero-stabilizzata, divisi in due gruppi in base alla presenza di instabilità soggettiva in flessione. Confronto del segno del cassetto posteriore, del test del cassetto anteriore a 90° e della radiografia sotto carico in ginocchio (variazione della traslazione tibio-femorale sotto carico, Δ-TPFA), con analisi ROC, accuratezza diagnostica e regressione logistica multivariabile aggiustata per età, sesso, BMI, follow-up, tipo di impianto e patologia lombare.",pop:"145 ginocchia protesizzate in 119 pazienti; 30 ginocchia (20,7%) con instabilità soggettiva.",results:"Δ-TPFA medio 1,40±3,75 mm nel gruppo instabile contro -1,17±3,28 mm nello stabile (p=0,001; AUC 0,68; IC 95% 0,56-0,80), predittore indipendente anche nell'analisi multivariabile (OR 1,30 per mm; IC 95% 1,11-1,52; p<0,001). Il segno del cassetto posteriore ha specificità 82,6% (IC 95% 74,6-88,4%) ed è associato in modo indipendente all'instabilità (OR 3,26; IC 95% 1,54-6,91; p=0,002). Il cassetto anteriore a 90° non discrimina (56,7% contro 47,0%; p=0,41).",concl:"Gli autori concludono che la radiografia sotto carico in ginocchio e il segno del cassetto posteriore aggiungono informazione utile nella valutazione dell'instabilità in flessione dopo protesi postero-stabilizzata, ma la discriminazione modesta del Δ-TPFA (AUC 0,68) indica che questi strumenti devono completare, non sostituire, la valutazione clinica; il test del cassetto anteriore a 90° va interpretato con cautela in questo contesto.",limits:"Studio retrospettivo monocentrico su una sola marca di impianto postero-stabilizzato non specificata nell'abstract · discriminazione solo modesta (AUC 0,68): una quota rilevante dei casi resta mal classificata al punto di cutoff proposto · instabilità soggettiva come esito, non un criterio radiografico o intraoperatorio oggettivo di riferimento.",perte:"Riguarda ogni tua protesi totale postero-stabilizzata: uno strumento diagnostico in più per l'instabilità in flessione, il motivo di insoddisfazione più spesso sottodiagnosticato dopo protesi — ma da usare insieme all'esame clinico, non al suo posto, vista la discriminazione solo modesta."}];
var SUGGQ=[{"k":"kol","n":"Kevin G. Shea","w":"Stanford University, Pediatric Orthopaedic Surgery (USA)","r":"Autore senior dello studio di oggi sul confronto ancora a sutura/tunnel osseo nella fissazione patellare dell'MPFL pediatrica: corrispondenza tecnica diretta con la tua fissazione dell'MPFL (ancore FiberTak, tecnica onlay) e con la tua pratica dai 14 anni in su. Sostituisce la proposta invariata di Tzu-Hao Tseng (12 settembre)."}];
var BRIEF_TEXT="La domenica apre con la settimana. I lavori che contano di più dal 7 al 13 settembre: oggi, una coorte propensity-matched di oltre diecimila pazienti mostra che il rinforzo laterale aggiunto alla ricostruzione del crociato anteriore porta più artrofibrosi, più chirurgia meniscale successiva e un'artrosi codificata più che raddoppiata a cinque anni, senza un beneficio dimostrato sulla nuova ricostruzione — il primo bilancio reale sui costi del gesto che esegui su ogni paziente. Il 10 settembre, una meta-analisi di 43 studi e oltre diciassettemila pazienti ha mostrato che il classico test del salto per il rientro allo sport predice il ritorno in campo ma non protegge in modo convincente dal reinfortunio. Il 7 settembre, per la prima volta il legame fra estrusione meniscale e mancata correzione è stato osservato dopo un'osteotomia tibiale, non solo dopo una sutura della radice: da misurare anche prima di un'osteotomia valgizzante. E il 9 settembre, una coorte di ventisei anni a Pittsburgh ha confermato che il tendine quadricipitale è l'innesto in ascesa nella ricostruzione del crociato, proprio la tua scelta. Due tensioni si sono mosse questa settimana: T1a due volte, prima con un rinforzo metodologico sulla scelta dell'innesto e oggi con il primo conto sui rischi del LET; T2b e T3 una volta ciascuna, sull'estrusione meniscale e sul test del salto. Oggi sei schede, nessuna rossa, due arancioni. Il lavoro scelto è la coorte sul database TriNetX appena descritta. Le altre cinque schede: uno studio cadaverico pediatrico mostra che il tunnel osseo tiene di più dell'ancora a sutura nella fissazione dell'MPFL, un segnale da conoscere per l'adolescente con osso meno denso; una serie di diciannove atleti d'élite mostra ottimi risultati aggiungendo l'osteotomia di riduzione dello slope alla revisione del crociato fallito; uno studio cadaverico confronta due sintesi per la stessa osteotomia, senza differenza nel carico di rottura ma con più micromovimento della placca biodegradabile sotto carico ciclico; una radiografia laterale standard del ginocchio si è mostrata affidabile per misurare la flessione femorale nativa, utile per la pianificazione personalizzata della protesi; e una coorte turca mostra che il segno del cassetto posteriore e una radiografia sotto carico aiutano a riconoscere l'instabilità in flessione dopo protesi postero-stabilizzata, con una discriminazione però solo modesta. Il raccoglitore notturno non è passato anche questa notte, decimo giorno consecutivo: richiami di dispositivi, Swissmedic, congressi, società e destino dei verdetti restano non verificati; le ritrattazioni sono state comunque ricontrollate a mano su PubMed per l'intero perimetro, senza nuovi esiti oltre a quello già noto.";
var BRIEF_DIALOGO=[{"chi":"A","t":"Oggi è domenica, quindi partiamo dalla settimana prima di arrivare al giorno."},{"chi":"B","t":"Che cosa ha contato di più?"},{"chi":"A","t":"Il lavoro di oggi: una coorte di oltre diecimila pazienti confronta chi riceve il rinforzo laterale insieme alla ricostruzione del crociato con chi no."},{"chi":"B","t":"E il risultato?"},{"chi":"A","t":"Con il rinforzo laterale più artrofibrosi, più interventi sul menisco dopo, e più diagnosi di artrosi a cinque anni, senza che diminuisca il bisogno di rioperare il legamento."},{"chi":"B","t":"Un problema, visto che lo esegui su ogni paziente."},{"chi":"A","t":"Sì, ma con un limite chiaro: lo studio non distingue il tipo di innesto né la tecnica del rinforzo, e nei pazienti più giovani il segnale è opposto. Non chiude la domanda sull'innesto rigido, apre però un conto sui costi del gesto."},{"chi":"B","t":"Che altro ha contato questa settimana?"},{"chi":"A","t":"Il dieci settembre, una meta-analisi su più di diciassettemila pazienti ha mostrato che il classico test del salto per il rientro allo sport predice chi torna in campo, ma non protegge davvero dal reinfortunio."},{"chi":"B","t":"E oggi, sulle osteotomie?"},{"chi":"A","t":"Due lavori: una serie di diciannove atleti d'élite con ottimi risultati aggiungendo la correzione dello slope alla revisione del crociato, e uno studio di laboratorio che confronta due modi di fissare la stessa osteotomia."},{"chi":"B","t":"Quindi per la tua pratica con la VELYS c'è qualcosa?"},{"chi":"A","t":"Sì: una radiografia laterale semplice del ginocchio si è mostrata affidabile per misurare la flessione naturale del femore, utile per pianificare la protesi in modo più su misura senza sempre una TC."},{"chi":"B","t":"E per finire?"},{"chi":"A","t":"Il raccoglitore notturno non è passato anche stanotte, decimo giorno di fila: richiami e congressi restano da verificare, ma le ritrattazioni sono state comunque controllate a mano su PubMed, senza sorprese."}];
